// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor, uint256 futureOffset) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);
        futureOffset = bound(futureOffset, 1 days + 1, 1000 days);
        uint256 ts = block.timestamp;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(ts + futureOffset);
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= ts + futureOffset);
    }
}
